on conflict (name) do nothing;

-- Sanity check: fail the migration loudly if the count drifts.
do $check$
declare
  n integer;
begin
  select count(*) into n from public.schools;
  if n <> 180 then
    raise exception
      'Expected 180 schools after seeding, found %. School list is incomplete.', n;
  end if;
end
$check$;
